// src/dom/events.js
function addListeners(listeners) {
  listeners.forEach(({ node, event, handler }) => {
    node.addEventListener(event, handler);
  });
}
function removeListeners(listeners) {
  listeners.forEach(({ node, event, handler }) => {
    node.removeEventListener(event, handler);
  });
}
function dispatchEvent(node, eventName, detail, options = {}) {
  node.dispatchEvent(
    new CustomEvent(eventName, {
      ...options,
      detail
    })
  );
}
function updateEvent(event, updates) {
  const { type, ...rest } = event;
  return new CustomEvent(event.type, {
    ...rest,
    ...updates
  });
}
function createListeners(listeners) {
  listeners = listeners || [];
  listeners.forEach((listener) => {
    const { node, event, handler } = listener;
    node.addEventListener(event, handler);
  });
  return {
    get list() {
      return listeners;
    },
    add({ node, event, handler }) {
      listeners.push({ node, event, handler });
      node.addEventListener(event, handler);
    },
    remove({ node, event, handler }) {
      const index = listeners.findIndex((listener) => {
        if (listener.node === node && listener.event === event && listener.handler === handler) {
          return true;
        }
        return false;
      });
      if (index !== -1) {
        listeners.splice(index, 1);
        node.removeEventListener(event, handler);
      }
    },
    clear() {
      listeners.forEach(({ node, event, handler }) => {
        listeners = [];
        node.removeEventListener(event, handler);
      });
    }
  };
}
export {
  addListeners,
  createListeners,
  dispatchEvent,
  removeListeners,
  updateEvent
};
